import{_ as t,o as r,c as o,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2017-JUN-08 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2017-JUN-08 :: Ceph Performance Weekly","date":"2017-06-21T00:00:00.000Z","updated":"2017-06-22T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","元数据缓存","Blue Store"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-JUN-08_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2017-JUN-08_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),l={name:"posts/2017/2017-JUN-08_-_-_Ceph_Performance_Weekly.md"};function n(a,e,i,p,_,g){return r(),o("div",null,[...e[0]||(e[0]=[s("<p>会议纪要：</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>会议主题</strong>： Ceph分布式存储项目讨论</p><p><strong>参会人员</strong>： Sage, Greg, Josh, James, Peter, Mohammad 等</p><p><strong>会议内容</strong>：</p><ul><li><strong>CDM会议回顾</strong>： 讨论了多个可用性操作问题，包括缓存、日志、扩展器重硬等。已合并的请求包括：scrub作业优先级调整、日志条目、扩展器重硬避免重叠、动态重硬、空批次事务提交、统计信息、unshare blob等。性能方面，luminous版本表现良好，parpc fast zero功能有潜力，但需进一步优化。</li><li><strong>监控器日志</strong>： 新增监控器命令，显示集群日志中最新的日志条目，并防止重复条目。</li><li><strong>元数据缓存</strong>： 讨论了元数据缓存配置，建议根据硬件配置进行调整，并考虑了Blue Store Cache和RocksDB Cache的配置。</li><li><strong>PG日志</strong>： 讨论了PG日志长度对性能和恢复时间的影响，建议将PG日志长度配置为内存占用量。</li><li><strong>Blue Store和RocksDB缓存</strong>： 调查了Blue Store和RocksDB缓存之间的交互，并考虑了压缩和未压缩缓存的影响。</li><li><strong>白名单回退设置</strong>： 讨论了白名单回退设置对性能的影响，并考虑了硬盘和SSD的设置。</li><li><strong>其他</strong>： 讨论了lmdb和buffer list的优化，以及使用SDVector替换SDList的可能性。</li></ul><p><strong>行动计划</strong>：</p><ul><li>Sage将测试不同缓存配置对性能的影响。</li><li>Josh将调查从PG日志中借用内存给Blue Store的可能性。</li><li>Peter将审查parpc fast zero功能。</li><li>James将调查白名单回退设置对性能的影响。</li><li>Mohammad将进行buffer list的基准测试。</li></ul><p><strong>后续会议</strong>：</p><ul><li>将在下周进行后续会议，继续讨论以上议题。</li></ul>",10)])])}const m=t(l,[["render",n]]);export{u as __pageData,m as default};
